  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Agomelatine absolute oral bioavailability was estimated at 3-4% in a human population PK analysis, well below the 20% threshold."
    },
    {
      "card_ids": ["C10"],
      "claim": "BMS-187745 absolute oral bioavailability was 2.6% in healthy male subjects after a 50 mg oral solution versus IV, below the 20% threshold."
    },
    {
      "card_ids": ["C12"],
      "claim": "Naltrexone oral tablet bioavailability ranged from 5% to 40%, crossing the 20% threshold, so this record is mixed and does not affirmatively support low bioavailability."
    }
