  "confidence": "high",
  "contradictory_card_ids": ["C12"],
  "decision_summary": "Direct human absolute/systemic bioavailability measurements for transferred molecules are consistently below 20% (2.6-11%), with high assay-transfer scores; the only mixed record (naltrexone 5-40%) crosses the threshold but does not outweigh the direct low measurements. Therefore predict low.",
  "evidence_gaps": [
    "C12 is a mixed range (5-40%) crossing the 20% threshold.",
    "C07 and C04 are qualitative ('poor', 'extremely low') without numeric threshold-relevant values and were discounted.",
    "C05 is a single-patient estimate with a maximum <1.7%."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C16", "C10"],
